function hasSameDigits(s) {
  const digits = Array.from(s, Number);
  let length = digits.length;
  while (length > 2) {
    for (let i = 0; i + 1 < length; i++) {
      digits[i] = (digits[i] + digits[i + 1]) % 10;
    }
    length--;
  }
  return digits[0] === digits[1];
}

