function hasSameDigits(s) {
  // After n - 2 rounds each final digit is the original digits weighted by row n - 2 of Pascal's triangle (mod 10).
  const n = s.length;
  let row = [1];
  for (let r = 0; r < n - 2; r++) {
    const next = [1];
    for (let j = 1; j < row.length; j++) next.push((row[j - 1] + row[j]) % 10);
    next.push(1);
    row = next;
  }
  let first = 0;
  let second = 0;
  for (let j = 0; j < row.length; j++) {
    first = (first + row[j] * Number(s[j])) % 10;
    second = (second + row[j] * Number(s[j + 1])) % 10;
  }
  return first === second;
}

