function generate(rand, size) {
  const pick = count => Math.floor(rand() * count);
  const n = size === 'large' ? 90 + pick(11) : 3 + pick(8);
  // Narrow digit sets (one digit, or 0 and 5) make equal final digits common; all ten digits make them rare.
  const alphabet = ['0123456789', '0123456789', '05', '28', '7'][pick(5)];
  let s = '';
  for (let i = 0; i < n; i++) s += alphabet[pick(alphabet.length)];
  return [s];
}
